/* CRM Conveniência — UI em JS puro, persistência via Cloudflare D1 */
const $=s=>document.querySelector(s), BRL=v=>(Number(v||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), cents=v=>Math.round(Number(String(v??0).replace(',','.'))*100), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), date=s=>s?new Date(s.length===10?s+'T12:00:00':s.replace(' ','T')+'Z').toLocaleDateString('pt-BR'):'—';
const cats=['CERVEJAS','REFRIGERANTES','DESTILADOS','DRINKS','SALGADINHOS','DOCES','SALGADOS','LANCHES','PORÇÕES','CIGARROS','TABACARIA','OUTROS'];
const methods={cash:'Dinheiro',pix:'PIX',debit:'Débito',credit:'Crédito',fiado:'Fiado'};
const nav=[['dashboard','▦','Painel geral'],['pdv','⚡','Venda rápida'],['orders','☷','Comandas'],['products','▣','Estoque / Produtos'],['customers','♙','Clientes'],['suppliers','♧','Fornecedores'],['receivables','↓','Contas a receber'],['payables','↑','Contas a pagar'],['cash','◉','Caixa único'],['report','▤','Fechamento do mês'],['backup','⬇','Fazer backup geral'],['business','⚙','Configurações do meu negócio']];
const menuSections=[{id:'vendas',label:'VENDAS',icon:'pdv',items:[['pdv','Venda rápida'],['orders','Comandas']]},{id:'stock',label:'ESTOQUE',icon:'products',stock:true,items:['CERVEJAS','REFRIGERANTES','DOSES','DESTILADOS','DOCES','SALGADOS','SALGADINHOS','PORÇÕES','LANCHES','DRINKS','CIGARROS','TABACARIA','OUTROS']},{id:'cadastros',label:'CADASTROS',icon:'customers',items:[['customers','Clientes'],['suppliers','Fornecedores']]},{id:'financeiro',label:'FINANCEIRO',icon:'cash',items:[['cash','Caixa único'],['receivables','Contas a receber'],['payables','Contas a pagar'],['report','Fechamento do mês']]},{id:'config',label:'CONFIGURAÇÕES',icon:'backup',items:[['backup','Fazer backup geral'],['business','Configurações do meu negócio']]}];
const navOpened=new Set(['vendas']);
let businessInfo={name:'CRM CONVENIÊNCIA',legal_name:'',cnpj:'',phone:'(42) 99999-4679',address:'Rua Aderly Turek, 81 - Cará-Cará, Ponta Grossa - PR, 84033-101',logo:''};let activeApi=0;let exited=false;
const state={page:'dashboard',db:null,cart:[],manual:[],order:null,category:'TODOS',search:'',report:null,stockCategory:'',stockExpanded:false};
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.style.display='block';t.style.background=bad?'#b12b41':'#113b79';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200)}
async function api(path,method='GET',body){activeApi++;try{let r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)}),d=await r.json().catch(()=>({error:'Resposta inválida da API'}));if(!r.ok)throw Error(d.error||`Erro ${r.status}`);return d}finally{activeApi--}}
async function refresh(){state.db=await api('bootstrap');$('#connection').textContent='● D1 conectado';$('#connection').classList.remove('offline')}
async function page(p){state.page=p;state.order=null;state.search='';state.category='TODOS';if(p!=='products')state.stockCategory='';document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#page-title').textContent=nav.find(n=>n[0]===p)?.[2]||'CRM';paintNav();$('.sidebar').classList.remove('open');try{await refresh();const render={dashboard, pdv,orders,products,customers,suppliers,receivables,payables,cash,report,backup,business}[p];await render()}catch(e){$('#connection').textContent='● D1 indisponível';$('#connection').classList.add('offline');$('#main').innerHTML=`<div class="card warning"><h2>Não foi possível acessar o D1</h2><p>${esc(e.message)}</p><p>Configure o binding <b>DB</b> e execute <code>schema.sql</code> e <code>seed.sql</code> no Cloudflare D1 (ambiente de produção).</p><button class="button" onclick="page('${p}')">Tentar novamente</button></div>`}}
function head(t,desc='',actions=''){return `<div class="head"><div><h1>${t}</h1><p>${desc}</p></div><div class="row">${actions}</div></div>`}
function card(label,value,sub=''){return `<div class="card metric"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function empty(t='Nenhum registro ainda.'){return `<div class="empty">${t}</div>`}
function input(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input class="input" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function moneyInput(label,name,value=0){return input(label,name,(value/100).toFixed(2),'number','min="0" step="0.01" required')}
function modal(title,html,onSave){$('#modal-title').textContent=title;$('#modal-body').innerHTML=`<form id="modal-form">${html}<div class="form-actions"><button type="button" class="button outline" id="cancelModal">Cancelar</button><button type="submit" class="button">Salvar</button></div></form>`;$('#modal').classList.remove('hidden');$('#cancelModal').onclick=closeModal;$('#modal-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{await onSave(b);closeModal();if(state.page==='pdv'){renderPdv()}else{await page(state.page)}toast('Salvo com sucesso')}catch(err){toast(err.message,true)}}}
function closeModal(){$('#modal').classList.add('hidden')}
function selectMethods(val='pix',includeFiado=false){return select('Forma de pagamento','method',Object.entries(methods).filter(([k])=>includeFiado||k!=='fiado'),val)}
function productOptions(){return state.db.products.filter(p=>p.active).map(p=>[p.id,`${p.name} (${p.unit}) — ${p.stock} disponível`])}
function categoryOptions(){return cats.map(c=>[c,c])}
function confirmAction(message){return window.confirm(message)}
function amountFor(name,b){let x=cents(b[name]);if(!Number.isSafeInteger(x)||x<0)throw Error('Valor inválido');return x}
function money(v){return BRL(v)}
async function dashboard(){const b=state.db;let low=b.products.filter(p=>p.active&&p.stock<=p.min_stock),debt=b.customers.reduce((a,c)=>a+Math.max(0,c.debt),0),open=b.orders.length;$('#main').innerHTML=head('Bem-vindo, Cláudio!','Visão geral do seu estabelecimento',`<button class="button" onclick="page('pdv')">⚡ Nova venda</button>`)+`<div class="grid four">${card('Caixa único',money(b.balance),'Saldo consolidado de movimentações')}${card('Fiado em aberto',money(debt),'Clientes com saldo pendente')}${card('Comandas abertas',open,'Consumos ainda não encerrados')}${card('Produtos ativos',b.products.filter(x=>x.active).length,'Itens cadastrados no estoque')}</div><div class="grid two"><div class="card"><h3>Acesso rápido</h3><div class="row"><button class="button" onclick="page('pdv')">Venda rápida</button><button class="button outline" onclick="page('orders')">Comandas</button><button class="button outline" onclick="page('products')">Estoque</button><button class="button outline" onclick="page('report')">Fechamento do mês</button></div></div><div class="card"><h3>⚠ Estoque no mínimo</h3>${low.length?low.slice(0,10).map(p=>`<div class="list-item"><span>${esc(p.name)}</span><b>${p.stock} ${p.unit}</b></div>`).join(''):empty('Nenhum produto abaixo do mínimo cadastrado.')}</div></div><div class="warning">O caixa único é um resumo de movimentações. Valores de cartão podem não estar disponíveis imediatamente na conta bancária. Cadastre valores de custo e venda antes das operações reais.</div>`}
function ptype(p){return p.kind==='recipe'?'Receita':p.kind==='ingredient'?'Insumo':'Produto'}
async function products(){let b=state.db.products;let category=state.stockCategory;const doseOnly=category==='DOSES';$('#main').innerHTML=head(doseOnly?'Estoque — Doses':category?'Estoque — '+category:'Estoque e produtos','Cadastre, edite, movimente e consulte o estoque. Doses compartilham estoque com as garrafas.',`<button class="button" onclick="editProduct()">＋ Adicionar produto</button><button class="button outline" onclick="showPresentations()">Caixas / doses</button>`)+`<div class="card"><div class="row"><input class="input" id="prodSearch" placeholder="Localizar produto..." style="max-width:340px"><select id="prodCategory" style="max-width:220px"><option value="">Todas as categorias</option>${cats.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Tipo</th><th>Estoque</th><th>Custo</th><th>Venda</th><th>Ações</th></tr></thead><tbody id="prodBody"></tbody></table></div></div>`;
let doseRows=[];if(doseOnly){try{doseRows=(await api('presentations')).filter(x=>x.active&&/dose/i.test(x.name))}catch(e){toast('Não foi possível carregar doses: '+e.message,true)}}
const render=()=>{let q=$('#prodSearch').value.toLowerCase(),c=$('#prodCategory').value;
if(doseOnly){let rows=doseRows.filter(d=>d.product_name.toLowerCase().includes(q)||d.name.toLowerCase().includes(q));$('#prodBody').innerHTML=rows.map(d=>{let p=b.find(p=>p.id===d.product_id);return `<tr><td><b>${esc(d.product_name)} — ${esc(d.name)}</b></td><td>DOSES</td><td>Apresentação</td><td>${p?Math.floor(p.stock/d.quantity):0} doses possíveis</td><td>${p?money(p.cost*d.quantity):'—'}</td><td>${money(d.price)}</td><td><button class="button sm outline" onclick="showPresentations()">Gerenciar doses</button></td></tr>`}).join('')||`<tr><td colspan="7">${empty('Nenhuma dose encontrada. Cadastre em Caixas / doses.')}</td></tr>`;return;}
$('#prodBody').innerHTML=b.filter(p=>p.active&&p.name.toLowerCase().includes(q)&&(!c||p.category===c)).map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.category)}</td><td>${ptype(p)}</td><td><span class="pill ${p.stock<=p.min_stock?'red':'green'}">${p.stock} ${p.unit}</span></td><td>${money(p.cost)}${p.unit==='ml'||p.unit==='g'?'/'+p.unit:''}</td><td>${money(p.price)}</td><td class="actions"><button class="button sm outline" onclick="editProduct(${p.id})">Editar</button><button class="button sm soft" onclick="adjustStock(${p.id})">Movimentar</button><button class="button sm danger" onclick="deleteProduct(${p.id})">Excluir</button></td></tr>`).join('')||`<tr><td colspan="7">${empty('Nenhum produto encontrado.')}</td></tr>`};$('#prodSearch').oninput=render;$('#prodCategory').onchange=e=>{state.stockCategory=e.target.value;render()};render()}
function stockFilter(category){state.stockExpanded=true;state.stockCategory=category;page('products')}
function toggleStock(){state.stockExpanded=!state.stockExpanded;document.querySelectorAll('.stock-submenu').forEach(e=>e.classList.toggle('expanded',state.stockExpanded))}
function editProduct(id){let p=state.db.products.find(p=>p.id===id)||{name:'',category:'CERVEJAS',kind:'simple',unit:'un',stock:0,min_stock:0,cost:0,price:0,favorite:0};modal(id?'Editar produto':'Adicionar produto',`<div class="form-grid">${input('Nome do produto','name',p.name,'text','required')}${select('Categoria','category',categoryOptions(),p.category)}${id?`<div class="field">Tipo: ${ptype(p)}<small>Tipo e unidade não podem ser alterados após o cadastro.</small></div>`:select('Tipo','kind',[['simple','Produto normal'],['ingredient','Ingrediente / insumo'],['recipe','Receita (drink ou lanche)']],'simple')}${id?'':select('Unidade de estoque','unit',[['un','Unidades'],['ml','Mililitros'],['g','Gramas']],'un')}${input('Quantidade em estoque','stock',p.stock,'number','min="0" required')}${input('Estoque mínimo','min_stock',p.min_stock,'number','min="0"')}${moneyInput('Custo por unidade básica','cost',p.cost)}${moneyInput('Valor de venda','price',p.price)}${select('Produto favorito no PDV','favorite',[['0','Não'],['1','Sim']],String(p.favorite||0))}</div><p class="muted small">Ex.: garrafa de 700 ml pode ser cadastrada como insumo com estoque em ml (700 por garrafa). A dose de 50 ml usa uma apresentação de quantidade 50. Receita exige ficha técnica para vender.</p>`,async b=>{let payload={...b,stock:Number(b.stock),min_stock:Number(b.min_stock),cost:amountFor('cost',b),price:amountFor('price',b),favorite:b.favorite==='1'};if(id)await api('products','PUT',{...payload,id});else await api('products','POST',payload)})}
async function deleteProduct(id){let p=state.db.products.find(x=>x.id===id);if(!confirmAction(`Excluir "${p.name}"? Se tiver histórico de venda/receita, será arquivado para preservar os registros.`))return;try{let r=await api('products','DELETE',{id});await page('products');toast(r.archived?'Produto arquivado: histórico preservado':'Produto excluído')}catch(e){toast(e.message,true)}}
function adjustStock(id){let p=state.db.products.find(p=>p.id===id);modal('Movimentação de estoque — '+p.name,`<p>Estoque atual: <b>${p.stock} ${p.unit}</b></p><div class="form-grid">${input('Quantidade (positiva entra / negativa sai)','quantity',0,'number','required step="1"')}${moneyInput('Novo custo unitário (opcional)','unit_cost',0)}${input('Motivo','reason','Entrada / ajuste')}</div>`,async b=>await api('stock','POST',{product_id:id,quantity:Number(b.quantity),unit_cost:amountFor('unit_cost',b),reason:b.reason}))}
async function showPresentations(){let prs=await api('presentations'),products=state.db.products.filter(p=>p.active&&p.kind!=='recipe');modal('Apresentações: caixa / garrafa / dose',`<p class="muted">Quantidade é consumida da unidade básica do produto: 12 latas, 700 ml ou 50 ml.</p><div class="table-wrap"><table><tr><th>Produto</th><th>Apresentação</th><th>Consumo</th><th>Preço</th></tr>${prs.map(p=>`<tr><td>${esc(p.product_name)}</td><td>${esc(p.name)}</td><td>${p.quantity}</td><td>${money(p.price)}</td></tr>`).join('')}</table></div><hr class="divider"><div class="form-grid">${select('Produto','product_id',products.map(p=>[p.id,p.name]))}${input('Nome da apresentação','name','','text','required')}${input('Unidades ou ml por venda','quantity',1,'number','min="1" required')}${moneyInput('Preço desta apresentação','price')}</div>`,async b=>await api('presentations','POST',{product_id:Number(b.product_id),name:b.name,quantity:Number(b.quantity),price:amountFor('price',b)}))}
async function showRecipes(){let recipes=await api('recipes'),products=state.db.products;modal('Ficha técnica — drinks e lanches',`<p class="muted">Cada venda desconta todos os ingredientes. Use quantidades na unidade de estoque cadastrada (un, ml ou g).</p><div class="table-wrap"><table><tr><th>Receita</th><th>Ingrediente</th><th>Quantidade</th><th></th></tr>${recipes.map(r=>`<tr><td>${esc(r.product_name)}</td><td>${esc(r.ingredient_name)}</td><td>${r.quantity}</td><td><button type="button" class="button sm danger" onclick="removeRecipe(${r.product_id},${r.ingredient_id})">Remover</button></td></tr>`).join('')}</table></div><hr class="divider"><div class="form-grid">${select('Drink / lanche','product_id',products.filter(p=>p.kind==='recipe'&&p.active).map(p=>[p.id,p.name]))}${select('Ingrediente','ingredient_id',products.filter(p=>p.kind!=='recipe'&&p.active).map(p=>[p.id,p.name+' ('+p.unit+')']))}${input('Quantidade por porção','quantity',1,'number','required min="1"')}</div>`,async b=>await api('recipes','POST',{product_id:Number(b.product_id),ingredient_id:Number(b.ingredient_id),quantity:Number(b.quantity)}))}
async function removeRecipe(product_id,ingredient_id){if(!confirmAction('Remover ingrediente da receita?'))return;try{await api('recipes','DELETE',{product_id,ingredient_id});closeModal();await page('products');toast('Ingrediente removido')}catch(e){toast(e.message,true)}}
function customerForm(id){let c=state.db.customers.find(c=>c.id===id)||{name:'',nickname:'',phone:'',cpf:'',credit_limit:0,blocked:0};modal(id?'Editar cliente':'Novo cliente',`<div class="form-grid">${input('Nome completo','name',c.name,'text','required')}${input('Apelido','nickname',c.nickname)}${input('Telefone / WhatsApp','phone',c.phone,'tel')}${input('CPF (opcional)','cpf',c.cpf)}${moneyInput('Limite individual de fiado','credit_limit',c.credit_limit)}${select('Situação do crédito','blocked',[['0','Liberado'],['1','Bloqueado']],String(c.blocked))}</div>`,async b=>await api('customers',id?'PUT':'POST',{...b,...id?{id}:{},credit_limit:amountFor('credit_limit',b),blocked:b.blocked==='1'}))}
async function customers(){let cs=state.db.customers;$('#main').innerHTML=head('Cadastro de clientes','Comandas individuais, crédito e histórico de fiado',`<button class="button" onclick="customerForm()">＋ Cadastrar cliente</button>`)+`<div class="card"><input id="clientSearch" class="input" placeholder="Pesquisar por nome ou apelido..." style="max-width:370px"><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Telefone</th><th>Limite</th><th>Saldo devedor</th><th>Disponível</th><th>Ações</th></tr></thead><tbody id="clientBody"></tbody></table></div></div>`;let r=()=>$('#clientBody').innerHTML=cs.filter(c=>(c.name+' '+c.nickname).toLowerCase().includes($('#clientSearch').value.toLowerCase())).map(c=>`<tr><td><b>${esc(c.name)}</b><br><span class="muted">${esc(c.nickname)}</span></td><td>${esc(c.phone)}</td><td>${money(c.credit_limit)}</td><td class="${c.debt>0?'bad':''}">${money(c.debt)}</td><td>${money(Math.max(0,c.credit_limit-c.debt))} ${c.blocked?'🔒':''}</td><td><button class="button sm outline" onclick="customerForm(${c.id})">Editar</button> <button class="button sm soft" onclick="showCustomerLedger(${c.id})">Extrato</button></td></tr>`).join('')||`<tr><td colspan="6">${empty()}</td></tr>`;$('#clientSearch').oninput=r;r()}
async function showCustomerLedger(id){let c=state.db.customers.find(c=>c.id===id),lines=await api('ledger?customer_id='+id);modal('Extrato — '+c.name,`<p>Saldo devedor: <b>${money(c.debt)}</b> · Limite: ${money(c.credit_limit)}</p><div class="table-wrap"><table><tr><th>Data</th><th>Descrição</th><th>Movimento</th></tr>${lines.map(x=>`<tr><td>${date(x.created_at)}</td><td>${esc(x.description)}</td><td class="${x.amount>0?'bad':'good'}">${money(x.amount)}</td></tr>`).join('')}</table></div><button type="button" class="button outline" onclick="printTable('Extrato de ${esc(c.name)}',document.querySelector('#modal-body .table-wrap').innerHTML)">Imprimir / PDF</button>`,async()=>{})}
function supplierForm(id){let s=state.suppliers.find(s=>s.id===id)||{name:'',contact:'',phone:'',email:'',notes:''};modal(id?'Editar fornecedor':'Cadastrar fornecedor',`<div class="form-grid">${input('Nome / razão social','name',s.name,'text','required')}${input('Contato','contact',s.contact)}${input('Telefone','phone',s.phone,'tel')}${input('E-mail','email',s.email,'email')}<label class="field full">Observações<textarea name="notes">${esc(s.notes)}</textarea></label></div>`,async b=>await api('suppliers',id?'PUT':'POST',{...b,...id?{id}:{}}))}
async function suppliers(){state.suppliers=await api('suppliers');$('#main').innerHTML=head('Fornecedores','Cadastro simples para contato e compras',`<button class="button" onclick="supplierForm()">＋ Novo fornecedor</button>`)+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Fornecedor</th><th>Contato</th><th>Telefone</th><th>E-mail</th><th>Ações</th></tr></thead><tbody>${state.suppliers.map(s=>`<tr><td><b>${esc(s.name)}</b><br><span class="muted">${esc(s.notes)}</span></td><td>${esc(s.contact)}</td><td>${esc(s.phone)}</td><td>${esc(s.email)}</td><td><button class="button sm outline" onclick="supplierForm(${s.id})">Editar</button> <button class="button sm danger" onclick="deleteSupplier(${s.id})">Excluir</button></td></tr>`).join('')||`<tr><td colspan="5">${empty()}</td></tr>`}</tbody></table></div></div>`}
async function deleteSupplier(id){if(!confirmAction('Excluir este fornecedor?'))return;try{await api('suppliers','DELETE',{id});await page('suppliers');toast('Fornecedor excluído')}catch(e){toast(e.message,true)}}
let presCache=[];
async function pdv(){presCache=await api('presentations');state.cart=[];state.manual=[];renderPdv()}
function catalogItems(){let all=[];for(const p of state.db.products.filter(p=>p.active&&(p.kind!=='ingredient'||p.price>0||presCache.some(v=>v.product_id===p.id)))){if(p.kind!=='ingredient'||p.price>0)all.push({key:p.id+'-0',id:p.id,pid:null,name:p.name,category:p.category,price:p.price,stock:p.stock,unit:p.unit,kind:p.kind});for(const pr of presCache.filter(v=>v.product_id===p.id&&v.active))all.push({key:p.id+'-'+pr.id,id:p.id,pid:pr.id,name:p.name+' · '+pr.name,category:p.category,price:pr.price,stock:p.stock,unit:p.unit,kind:p.kind})}return all}
function renderPdv(){const items=catalogItems().filter(p=>(state.category==='TODOS'||p.category===state.category)&&p.name.toLowerCase().includes(state.search.toLowerCase())),total=state.cart.reduce((s,i)=>s+i.price*i.qty,0)+state.manual.reduce((s,i)=>s+i.price*i.qty,0);$('#main').innerHTML=head('Venda rápida','Pegou, pagou e saiu — sem cadastro de cliente')+`<div class="split"><div class="card"><input id="searchPdv" class="input" placeholder="Buscar produto pelo nome..." value="${esc(state.search)}"><div class="pills">${['TODOS',...cats,'FORA DE ESTOQUE'].map(c=>`<button class="tab ${state.category===c?'active':''}" onclick="${c==='FORA DE ESTOQUE'?'openManualSale()':`setPdvCat('${c}')` }">${c==='FORA DE ESTOQUE'?'＋ INSERIR PRODUTO FORA DE ESTOQUE':c}</button>`).join('')}</div><div class="products">${items.map(p=>`<button class="product-btn" ${p.stock<=0||p.price<=0?'disabled':''} onclick="addCart('${p.key}')"><b>${esc(p.name)}</b><span>${money(p.price)}</span><small>${p.stock} ${p.unit} ${p.price<=0?'· Cadastre o preço':''}</small></button>`).join('')||empty('Nada encontrado.')}</div></div><div class="card"><div class="row between"><h3>Carrinho</h3><button class="button sm outline" onclick="state.cart=[];state.manual=[];renderPdv()">Limpar</button></div>${state.manual.map((i,index)=>`<div class="cart-line"><div class="name"><b>${esc(i.name)}</b><div class="muted small">Produto avulso · sem baixa no estoque</div></div><span class="qty">${i.qty}×</span><button class="button sm outline" onclick="removeManual(${index})">−</button><b>${money(i.price*i.qty)}</b></div>`).join('')}${state.cart.map(i=>`<div class="cart-line"><div class="name"><b>${esc(i.name)}</b><div class="muted small">${money(i.price)} cada</div></div><span class="qty">${i.qty}×</span><button class="button sm outline" onclick="removeCart('${i.key}')">−</button><b>${money(i.price*i.qty)}</b></div>`).join('')}${!(state.cart.length||state.manual.length)?empty('Selecione os produtos.'):''}<div class="cart-total"><span>Total</span><strong>${money(total)}</strong></div><label class="field">Forma de pagamento<select id="quickMethod">${Object.entries(methods).filter(([m])=>m!=='fiado').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button class="button wide green" style="margin-top:15px" ${!(state.cart.length||state.manual.length)?'disabled':''} onclick="finishQuick()">✓ Confirmar venda e baixar estoque</button></div></div>`;$('#searchPdv').oninput=e=>{state.search=e.target.value;renderPdv();$('#searchPdv').focus();$('#searchPdv').setSelectionRange(state.search.length,state.search.length)}}
function openManualSale(){modal('Inserir produto fora de estoque',`<p class="muted">Esta venda será registrada no caixa e fechamento mensal, mas não altera o estoque. Não cadastra um produto permanente.</p><div class="form-grid">${input('Produto','name','','text','required maxlength="200"')}${input('Quantidade','qty',1,'number','required min="1" max="10000" step="1"')}${moneyInput('Valor de venda por unidade','price',0)}</div>`,async b=>{const qty=Number(b.qty),price=amountFor('price',b),name=String(b.name||'').trim();if(!name||!Number.isInteger(qty)||qty<1||qty>10000||price<=0)throw Error('Informe produto, quantidade e valor válidos');state.manual.push({name,qty,price})})}
function removeManual(i){state.manual.splice(i,1);renderPdv()}
function setPdvCat(c){state.category=c;renderPdv()}
function addCart(k){let p=catalogItems().find(p=>p.key===k);if(!p)return;let item=state.cart.find(x=>x.key===k);if(item)item.qty++;else state.cart.push({...p,qty:1});renderPdv()}
function removeCart(k){let item=state.cart.find(x=>x.key===k);if(item){item.qty--;if(!item.qty)state.cart=state.cart.filter(x=>x.key!==k)}renderPdv()}
async function finishQuick(){let method=$('#quickMethod').value,items=state.cart.map(x=>({product_id:x.id,presentation_id:x.pid,quantity:x.qty})),total=state.cart.reduce((s,i)=>s+i.price*i.qty,0)+state.manual.reduce((s,i)=>s+i.price*i.qty,0);if(!confirmAction('Confirmar recebimento de '+money(total)+' e baixar estoque?'))return;try{await api('sales/quick','POST',{items,manual:state.manual,method});state.cart=[];state.manual=[];await page('pdv');toast('Venda registrada! Estoque atualizado.')}catch(e){toast(e.message,true)}}
async function orders(){let os=await api('orders/all');$('#main').innerHTML=head('Comandas individuais','Consumo no local, pagamentos parciais e PDF',`<button class="button" onclick="newOrder()">＋ Abrir comanda</button>`)+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Comanda</th><th>Cliente</th><th>Situação</th><th>Total</th><th>Pago</th><th>Saldo</th><th>Ações</th></tr></thead><tbody>${os.map(o=>{let owed=o.total-o.paid_amount;let status=o.status==='cancelled'?'Cancelada':o.status==='credit'?'Fiado':o.status==='paid'?'Quitada':owed===0&&o.total>0?'Quitada · aberta':o.paid_amount>0?'Parcial':'Aberta';return `<tr class="${status.includes('Quitada')?'state-paid':status==='Parcial'?'state-partial':''}"><td>#${o.id}</td><td>${esc(o.customer_name)}</td><td><span class="pill ${status.includes('Quitada')?'green':status==='Parcial'?'yellow':''}">${status}</span></td><td>${money(o.total)}</td><td>${money(o.paid_amount)}</td><td>${money(o.status==='credit'?o.total-o.paid_amount:owed)}</td><td><button class="button sm outline" onclick="showOrderDetails(${o.id})">Ver / PDF</button>${o.status==='open'?` <button class="button sm" onclick="openOrder(${o.id})">Editar</button>`:''}</td></tr>`}).join('')||`<tr><td colspan="7">${empty('Nenhuma comanda registrada.')}</td></tr>`}</tbody></table></div></div>`}
async function showOrderDetails(id){let os=await api('orders/all'),o=os.find(x=>x.id===id),items=await api('order-items?order_id='+id),payments=await api('orders/payments?order_id='+id);if(!o)throw Error('Comanda não encontrada');let text=orderPdfLines(o,items,payments);modal('Comanda #'+id+' — '+o.customer_name,`<div class="table-wrap"><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Valor</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.quantity}</td><td>${money(i.quantity*i.unit_price)}</td></tr>`).join('')}</tbody></table></div><p><b>Total: ${money(o.total)} · Pago: ${money(o.paid_amount)} · Restante: ${money(o.total-o.paid_amount)}</b></p><button type="button" class="button" id="sendOrderPdf">📄 ENVIAR PDF</button>`,async()=>{});$('#sendOrderPdf').onclick=()=>sharePdf('Comanda-'+id+'.pdf',text)}
function orderPdfLines(o,items,payments){return ['CRM CONVENIÊNCIA','COMANDA #'+o.id+' - '+o.customer_name,'Emitida em '+new Date().toLocaleString('pt-BR'),'','CONSUMOS',...items.map(i=>`${i.quantity} x ${i.name} - ${money(i.quantity*i.unit_price)}`),'','PAGAMENTOS',...payments.map(i=>`${date(i.created_at)} - ${methods[i.method]||i.method}: ${money(i.amount)}`),'','VALOR TOTAL: '+money(o.total),'VALOR PAGO: '+money(o.paid_amount),'SALDO: '+money(o.total-o.paid_amount)]}
function newOrder(){let cs=state.db.customers;if(!cs.length){toast('Cadastre um cliente primeiro',true);return}modal('Abrir comanda',`<div class="form-grid">${select('Cliente cadastrado','customer_id',cs.map(c=>[c.id,c.name+(c.nickname?' · '+c.nickname:'')]))}</div>`,async b=>await api('orders','POST',{customer_id:Number(b.customer_id)}))}
async function openOrder(id){try{const order=state.db.orders.find(o=>o.id===id),its=await api('order-items?order_id='+id),prs=await api('presentations');state.order=order;let ps=state.db.products.filter(p=>p.active&&(p.kind!=='ingredient'||p.price>0||prs.some(v=>v.product_id===p.id)));let pays=await api('orders/payments?order_id='+id),sumPaid=pays.reduce((a,i)=>a+i.amount,0);$('#main').innerHTML=head(`Comanda #${id} — ${esc(order.customer_name)}`,'Estoque é baixado assim que o consumo é lançado',`<button class="button outline" onclick="page('orders')">← Voltar</button>`)+`<div class="grid two"><div class="card"><h3>Adicionar consumo</h3><div class="form-grid">${select('Produto','product_id',ps.map(p=>[p.id,p.name]))}${select('Apresentação','presentation_id',[['','Padrão']], '')}${input('Quantidade','quantity',1,'number','min="1" required')}</div><button class="button wide" onclick="addOrderItem(${id})">＋ Adicionar à comanda</button></div><div class="card"><h3>Consumos registrados</h3>${its.map(i=>`<div class="cart-line"><div class="name">${esc(i.name)}<div class="muted small">${i.quantity} × ${money(i.unit_price)}</div></div><b>${money(i.quantity*i.unit_price)}</b><button class="button sm danger" onclick="removeOrderItem(${i.id},${id})">×</button></div>`).join('')||empty('Sem itens ainda.')}<div class="cart-total">Total <strong>${money(order.total)}</strong></div><p>Pago: <b>${money(sumPaid)}</b> · Saldo: <b>${money(order.total-sumPaid)}</b></p><div class="row"><button class="button outline" onclick="insertOrderPayment(${id})" ${order.total<=sumPaid?'disabled':''}>＋ Inserir pagamento</button><button class="button outline" onclick="showOrderDetails(${id})">📄 ENVIAR PDF</button></div><label class="field">Pagamento do saldo no fechamento<select id="orderMethod">${Object.entries(methods).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="field" style="margin-top:9px">Vencimento do fiado (opcional)<input class="input" type="date" id="orderDue"></label><div class="row" style="margin-top:13px"><button class="button green" onclick="closeOrder(${id})" ${!its.length?'disabled':''}>Fechar comanda</button><button class="button outline danger" onclick="cancelOrder(${id})">Cancelar comanda</button></div></div></div>`;let prSelect=$('[name=presentation_id]'),productSelect=$('[name=product_id]');function sync(){let list=prs.filter(p=>p.product_id===Number(productSelect.value)&&p.active);prSelect.innerHTML=`<option value="">Preço padrão</option>`+list.map(p=>`<option value="${p.id}">${esc(p.name)} (${money(p.price)})</option>`).join('')}productSelect.onchange=sync;sync()}catch(e){toast(e.message,true)}}
function insertOrderPayment(id){const o=state.db.orders.find(x=>x.id===id),paid=o.paid_amount||0;modal('Inserir pagamento — Comanda #'+id,`<p>Valor total ${money(o.total)} · Saldo atual <b>${money(o.total-paid)}</b></p><div class="form-grid">${moneyInput('Valor recebido','amount',o.total-paid)}${selectMethods('pix')}${input('Observação','note')}</div>`,async b=>{let amount=amountFor('amount',b);if(amount<1||amount>o.total-paid)throw Error('Valor maior que o saldo da comanda');await api('orders/payment','POST',{order_id:id,amount,method:b.method,note:b.note});await refresh();await openOrder(id)})}
async function addOrderItem(id){try{let b={order_id:id,product_id:Number($('[name=product_id]').value),presentation_id:Number($('[name=presentation_id]').value)||null,quantity:Number($('[name=quantity]').value)};let result=await api('order-items','POST',b);await refresh();await openOrder(id);toast(result.credit_warning?'Consumo lançado. Atenção: acima do limite para fiado.':'Consumo lançado e estoque baixado.',!!result.credit_warning)}catch(e){toast(e.message,true)}}
async function removeOrderItem(item_id,id){if(!confirmAction('Remover consumo e devolver ao estoque?'))return;try{await api('order-items','DELETE',{item_id});await refresh();await openOrder(id);toast('Item removido; estoque estornado')}catch(e){toast(e.message,true)}}
async function closeOrder(id){let method=$('#orderMethod').value,due_date=$('#orderDue').value;if(!confirmAction('Fechar a comanda com pagamento '+methods[method]+'?'))return;try{await api('orders/close','POST',{order_id:id,method,due_date});await page('orders');toast(method==='fiado'?'Comanda lançada no fiado':'Comanda paga e encerrada')}catch(e){toast(e.message,true)}}
async function cancelOrder(id){if(!confirmAction('Cancelar a comanda e devolver todos os itens ao estoque?'))return;try{await api('orders/cancel','POST',{order_id:id});await page('orders');toast('Comanda cancelada')}catch(e){toast(e.message,true)}}
async function receivables(){const os=await api('receivables/orders'),open=os.filter(o=>o.balance>0),cs=state.db.customers.filter(c=>c.debt>0);$('#main').innerHTML=head('Contas a receber','Comandas em aberto e dívidas fiadas',`<button class="button outline" onclick="printTable('Contas a receber',document.querySelector('#receivablesTable').outerHTML)">Imprimir / PDF</button>`)+`<div class="grid three">${card('Comandas a receber',money(open.reduce((s,o)=>s+o.balance,0)))}${card('Fiados encerrados',money(cs.reduce((s,c)=>s+c.debt,0)))}${card('Total pendente',money(open.reduce((s,o)=>s+o.balance,0)+cs.reduce((s,c)=>s+c.debt,0)))}</div><div class="card"><div class="table-wrap"><table id="receivablesTable"><thead><tr><th>Identificação</th><th>Total</th><th>Pago</th><th>Saldo devedor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${os.map(o=>`<tr class="${o.balance===0&&o.total>0?'state-paid':o.paid>0?'state-partial':''}"><td>Comanda nº ${o.id} — ${esc(o.customer_name)}</td><td>${money(o.total)}</td><td>${money(o.paid)}</td><td>${money(o.balance)}</td><td><span class="pill ${o.balance===0&&o.total>0?'green':o.paid>0?'yellow':''}">${o.balance===0&&o.total>0?'Quitada':o.paid>0?'Parcial':'Aberta'}</span></td><td class="no-print"><button class="button sm outline" onclick="openOrder(${o.id})">Abrir</button> <button class="button sm outline" onclick="showOrderDetails(${o.id})">PDF</button></td></tr>`).join('')}${cs.map(c=>`<tr><td>Fiado — ${esc(c.name)}</td><td>—</td><td>—</td><td>${money(c.debt)}</td><td><span class="pill yellow">Pendente</span></td><td class="no-print"><button class="button sm green" onclick="receive(${c.id})">Inserir pagamento</button> <button class="button sm outline" onclick="showCustomerLedger(${c.id})">Extrato</button></td></tr>`).join('')}${!os.length&&!cs.length?`<tr><td colspan="6">${empty('Nenhuma conta a receber.')}</td></tr>`:''}</tbody></table></div></div>`}
function receive(id){let c=state.db.customers.find(c=>c.id===id);modal('Receber fiado — '+c.name,`<p>Saldo atual: <b>${money(c.debt)}</b></p><div class="form-grid">${moneyInput('Valor recebido','amount',c.debt)}${selectMethods()}</div>`,async b=>{let amount=amountFor('amount',b);if(amount<=0)throw Error('Informe um valor');await api('customers/pay','POST',{customer_id:id,amount,method:b.method})})}
function payableForm(){modal('Nova conta a pagar',`<div class="form-grid">${input('Descrição','description','','text','required')}${select('Fornecedor','supplier',[['','Não informado'],...(state.suppliers||[]).map(s=>[s.name,s.name])])}${select('Categoria','category',[['Mercadorias','Mercadorias'],['Aluguel','Aluguel'],['Energia','Energia'],['Água','Água'],['Manutenção','Manutenção'],['Outros','Outros']])}${moneyInput('Valor da conta','amount')}${input('Data de vencimento','due_date',new Date().toISOString().slice(0,10),'date','required')}${select('Recorrente','recurring',[['0','Não'],['1','Sim (identificação)']],'0')}</div>`,async b=>await api('payables','POST',{...b,amount:amountFor('amount',b),recurring:b.recurring==='1'}))}
async function payables(){state.suppliers=await api('suppliers');const items=state.db.payables;$('#main').innerHTML=head('Contas a pagar','Fornecedores, compras e despesas',`<button class="button" onclick="payableForm()">＋ Nova despesa</button><button class="button outline" onclick="printTable('Contas a pagar',document.querySelector('#payablesTable').outerHTML)">Imprimir / PDF</button>`)+`<div class="grid three">${card('Total em aberto',money(items.reduce((s,i)=>s+i.amount-i.paid_amount,0)))}${card('Títulos pendentes',items.filter(i=>i.status!=='paid').length)}${card('Total pago nos títulos',money(items.reduce((s,i)=>s+i.paid_amount,0)))}</div><div class="card"><div class="table-wrap"><table id="payablesTable"><thead><tr><th>Descrição</th><th>Fornecedor</th><th>Vencimento</th><th>Valor</th><th>Pago</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.description)}</td><td>${esc(i.supplier)}</td><td>${date(i.due_date)}</td><td>${money(i.amount)}</td><td>${money(i.paid_amount)}</td><td><span class="pill ${i.status==='paid'?'green':i.due_date<new Date().toISOString().slice(0,10)?'red':''}">${i.status==='paid'?'Pago':'Em aberto'}</span></td><td class="no-print">${i.status!=='paid'?`<button class="button sm green" onclick="payPayable(${i.id})">Pagar</button>`:''}</td></tr>`).join('')||`<tr><td colspan="7">${empty()}</td></tr>`}</tbody></table></div></div>`}
function payPayable(id){let p=state.db.payables.find(x=>x.id===id);modal('Pagamento de conta — '+p.description,`<p>Em aberto: <b>${money(p.amount-p.paid_amount)}</b></p><div class="form-grid">${moneyInput('Valor a pagar','amount',p.amount-p.paid_amount)}${selectMethods()}</div>`,async b=>await api('payables/pay','POST',{id,amount:amountFor('amount',b),method:b.method}))}
async function cash(){let rows=await api('cash');$('#main').innerHTML=head('Caixa único','Dinheiro, PIX e cartões consolidados; histórico por forma de recebimento',`<button class="button" onclick="cashForm()">＋ Lançamento manual</button><button class="button outline" onclick="adjustCashBalance()">ALTERAR VALORES EM CAIXA</button><button class="button outline" onclick="printTable('Movimentações do caixa',document.querySelector('#cashTable').outerHTML)">Imprimir / PDF</button>`)+`<div class="grid three">${card('Saldo de movimentos',money(state.db.balance))}${card('Entradas registradas',money(rows.filter(r=>['income','opening'].includes(r.type)).reduce((s,r)=>s+r.amount,0)),'Últimos 300 movimentos')}${card('Saídas registradas',money(rows.filter(r=>r.type==='expense').reduce((s,r)=>s+r.amount,0)),'Últimos 300 movimentos')}</div><div class="card"><div class="table-wrap"><table id="cashTable"><thead><tr><th>Data</th><th>Tipo</th><th>Forma</th><th>Descrição</th><th>Valor</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${date(r.created_at)}</td><td>${esc(r.type)}</td><td>${esc(methods[r.method]||r.method)}</td><td>${esc(r.note)}</td><td class="${r.type==='expense'?'bad':'good'}">${r.type==='expense'?'-':'+'}${money(r.amount)}</td></tr>`).join('')||`<tr><td colspan="5">${empty()}</td></tr>`}</tbody></table></div></div>`}
function adjustCashBalance(){modal('Alterar valores em caixa',`<p>Saldo consolidado atual: <b>${money(state.db.balance)}</b></p><div class="form-grid">${moneyInput('Novo saldo desejado','target',Math.max(0,state.db.balance))}${selectMethods('cash')}${input('Justificativa obrigatória','reason','','text','required minlength="6"')}</div><p class="muted">Será criado um ajuste registrado no histórico, sem apagar lançamentos anteriores.</p>`,async b=>await api('cash/adjust','POST',{target:amountFor('target',b),method:b.method,reason:b.reason}))}
function cashForm(){modal('Lançamento manual de caixa',`<div class="form-grid">${select('Tipo','type',[['opening','Saldo inicial'],['income','Entrada manual'],['expense','Saída manual']])}${selectMethods('cash')}${moneyInput('Valor','amount')}${input('Descrição / justificativa','note','','text','required')}</div><p class="muted small">As vendas e o pagamento de contas já registram entradas e saídas automaticamente. Evite lançar novamente o mesmo movimento.</p>`,async b=>await api('cash','POST',{...b,amount:amountFor('amount',b)}))}
async function loadBusiness(){try{businessInfo=await api('business')}catch(e){toast('Configurações do negócio: execute a migração SQL da V1.3.0 ('+e.message+')',true)}return businessInfo}
async function business(){await loadBusiness();$('#main').innerHTML=head('Configurações do meu negócio','Dados usados nos documentos e relatórios em PDF')+`<div class="card"><form id="businessForm"><div class="form-grid">${input('Nome fantasia','name',businessInfo.name,'text','required maxlength="120"')}${input('Razão social','legal_name',businessInfo.legal_name)}${input('CNPJ','cnpj',businessInfo.cnpj)}${input('Telefone / WhatsApp','phone',businessInfo.phone)}<label class="field full">Endereço completo<textarea class="input" name="address" rows="3">${esc(businessInfo.address)}</textarea></label></div><label class="field">Logomarca <input class="input" id="businessLogo" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="muted small">Use PNG, JPG ou WebP. A imagem será reduzida antes de salvar no D1 (máximo de 160 KB). Deixe em branco para manter a logo atual.</p><img id="businessLogoPreview" alt="Logomarca atual" src="${businessInfo.logo||'/assets/logo-opcao10.png'}" style="width:180px;max-height:150px;object-fit:contain;margin:12px 0;border:1px solid #dce5f2;padding:8px;border-radius:12px"><div class="row"><button class="button" type="submit">Salvar configurações no D1</button></div></form></div>`;$('#businessLogo').onchange=async ev=>{try{let f=ev.target.files[0];if(!f)return;const u=await shrinkLogo(f);$('#businessLogoPreview').src=u;$('#businessLogoPreview').dataset.logo=u}catch(e){toast(e.message,true);ev.target.value=''}};$('#businessForm').onsubmit=async ev=>{ev.preventDefault();try{const f=ev.target,fd=new FormData(f);const d={name:fd.get('name'),legal_name:fd.get('legal_name'),cnpj:fd.get('cnpj'),phone:fd.get('phone'),address:fd.get('address'),logo:$('#businessLogoPreview').dataset.logo||businessInfo.logo};businessInfo=await api('business','POST',d);toast('Configurações salvas no D1!')}catch(e){toast(e.message,true)}}}
async function shrinkLogo(file){if(file.size>5_000_000)throw Error('Escolha uma imagem menor que 5 MB');let img=await createImageBitmap(file);let c=document.createElement('canvas');const scale=Math.min(1,480/img.width,240/img.height);c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);img.close?.();let u=c.toDataURL('image/jpeg',.76);if(u.length>215000)throw Error('A logomarca ainda está muito grande; use um arquivo menor');return u}
function leaveSystem(){if(activeApi){toast('Há uma operação sendo salva. Aguarde a conclusão antes de sair.',true);return}if(!$('#modal').classList.contains('hidden')){toast('Feche ou salve a janela aberta antes de sair.',true);return}if(!window.confirm('Deseja sair do CRM CONVENIÊNCIA? Os registros confirmados já estão salvos no D1. Alterações não confirmadas na tela não serão salvas.'))return;window.alert('TEJE LIVRE!');exited=true;$('#app').style.display='none';const screen=document.createElement('section');screen.className='exit-screen';screen.id='exit-screen';screen.innerHTML=`<img src="/assets/logo-icone.png" alt="CRM CONVENIÊNCIA"><h1>TEJE LIVRE!</h1><p>Você saiu da visualização do sistema.</p><button class="button" id="reenter">Voltar ao CRM</button><small>Sem autenticação, essa saída não impede novo acesso pelo link.</small>`;document.body.append(screen);screen.querySelector('#reenter').onclick=()=>{screen.remove();$('#app').style.display='flex';exited=false;page('dashboard')}}
async function backup(){$('#main').innerHTML=head('Fazer backup geral','Exportar uma cópia dos dados do Cloudflare D1 para o aparelho')+`<div class="card"><h2>Backup completo em JSON</h2><p>Inclui produtos, estoque, fornecedores, clientes, vendas, comandas, pagamentos e financeiro. Não altera nenhum registro.</p><p class="muted">Guarde o arquivo em local protegido. Ele pode conter dados pessoais. A restauração não é automática nesta versão.</p><button class="button" onclick="downloadBackup()">⬇ Baixar backup geral</button></div>`}
async function downloadBackup(){try{const data=await api('backup');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='CRM_CONVENIENCIA_BACKUP_'+new Date().toISOString().slice(0,19).replace(/:/g,'-')+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);toast('Backup gerado: salve o arquivo em local seguro')}catch(e){toast('Falha no backup: '+e.message,true)}}
async function report(){const m=new Date().toISOString().slice(0,7);$('#main').innerHTML=head('Fechamento do mês','Ranking, faturamento, fiado, caixa e resultado',`<label class="field">Mês de referência<input class="input" id="reportMonth" type="month" value="${m}"></label><button class="button" onclick="loadReport()">Consultar</button>`)+`<div id="reportBody"></div>`;await loadReport()}
async function loadReport(){try{const d=await api('report?month='+$('#reportMonth').value);state.report=d;let items=d.items||[],max=Math.max(1,...items.map(i=>i.qty)),revenue=items.reduce((a,i)=>a+i.revenue,0),cost=items.reduce((a,i)=>a+i.cost,0);$('#reportBody').innerHTML=`<div class="grid four">${card('Faturamento',money(d.sales.gross),d.sales.count+' vendas')}${card('Vendas fiadas no mês',money(d.sales.credit))}${card('Recebimentos',money(d.cash.income))}${card('Saídas registradas',money(d.cash.expense))}</div><div class="grid three">${card('Custo dos produtos vendidos',money(cost))}${card('Lucro bruto estimado',money(revenue-cost),'Sem despesas e impostos')}${card('Saldo de fiado atual',money(d.debts.balance),'Acumulado, não apenas no mês')}</div><div class="card" id="reportPrintable"><h2>CRM CONVENIÊNCIA — FECHAMENTO ${esc(d.month)}</h2><p>Ranking por unidades vendidas</p>${items.slice(0,20).map((i,n)=>`<div class="report-row"><span>${n+1}º ${esc(i.name)}</span><div class="bar"><span style="width:${100*i.qty/max}%"></span></div><b>${i.qty}</b></div>`).join('')||empty('Nenhuma venda no mês.') }<hr class="divider"><h3>Ranking por faturamento</h3><div class="table-wrap"><table><tr><th>Produto</th><th>Quantidade</th><th>Faturamento</th><th>Custo</th><th>Margem bruta</th></tr>${[...items].sort((a,b)=>b.revenue-a.revenue).map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${money(i.revenue)}</td><td>${money(i.cost)}</td><td>${money(i.revenue-i.cost)}</td></tr>`).join('')}</table></div><hr class="divider"><table><tr><td>Faturamento bruto</td><td>${money(d.sales.gross)}</td></tr><tr><td>Fiado vendido no período</td><td>${money(d.sales.credit)}</td></tr><tr><td>Entradas efetivamente registradas no mês</td><td>${money(d.cash.income)}</td></tr><tr><td>Saídas efetivamente registradas no mês</td><td>${money(d.cash.expense)}</td></tr><tr><td>Saldo líquido de movimentos no mês</td><td>${money(d.cash.net)}</td></tr><tr><td>Contas com vencimento no mês</td><td>${money(d.payables.obligations)}</td></tr><tr><td>Pagamentos acumulados dessas contas</td><td>${money(d.payables.paid)}</td></tr></table><p class="muted small">Margem bruta baseada nos custos cadastrados. O saldo líquido de caixa não representa lucro. Cartões podem ter prazos de liquidação e taxas não conciliadas.</p></div><div class="row"><button class="button" onclick="printReport()">▤ Exportar / salvar em PDF</button><button class="button outline" onclick="shareReport()">Compartilhar resumo</button></div>`}catch(e){toast(e.message,true)}}
function createPdf(lines){
 const cp={8364:128,8211:150,8212:151,8216:145,8217:146,8220:147,8221:148,8226:149};
 const bytes=s=>Uint8Array.from([...String(s)].map(ch=>{let k=ch.charCodeAt(0);return k<256?k:(cp[k]||63)}));
 const chunks=[];let off=0;const push=s=>{let b=typeof s==='string'?bytes(s):s;chunks.push(b);off+=b.length};
 const fmt=s=>String(s||'').replace(/[\\()]/g,x=>'\\'+x).replace(/[\r\n]/g,' ');
 const title=businessInfo.name||'CRM CONVENIÊNCIA',address=businessInfo.address||'',phone=businessInfo.phone||'';
 const pageCount=Math.max(1,Math.ceil(lines.length/37)),objects=[],offsets=[0],pageIds=[];let id=1;
 const catalog=id++,pagesId=id++,normalFont=id++,boldFont=id++;
 for(let pg=0;pg<pageCount;pg++){
  let content=`0.04 0.18 0.50 rg 0 754 595 88 re f\n0.15 0.37 0.77 rg 0 746 595 8 re f\n`;
  content+=`BT /FB 21 Tf 1 1 1 rg 38 801 Td (${fmt(title).slice(0,55)}) Tj ET\n`;
  content+=`BT /FN 9 Tf 0.9 0.94 1 rg 38 781 Td (${fmt(address).slice(0,103)}) Tj ET\n`;
  content+=`BT /FN 9 Tf 0.9 0.94 1 rg 38 765 Td (${fmt(phone).slice(0,80)}) Tj ET\n`;
  content+=`0.18 0.28 0.47 rg 37 719 522 1 re f\n`;
  let y=727;
  for(let i=pg*37;i<Math.min(lines.length,(pg+1)*37);i++){
   const txt=fmt(lines[i]).slice(0,111);const strong=i===0||/^TOTAL|^SALDO|^COMANDA|^FECHAMENTO/.test(txt);
   if(i%2===0){content+=`0.96 0.97 0.99 rg 36 ${y-5} 523 17 re f\n`}
   content+=`BT /${strong?'FB':'FN'} ${strong?11:10} Tf 0.11 0.2 0.35 rg 43 ${y} Td (${txt}) Tj ET\n`;y-=18;
  }
  content+=`0.75 0.80 0.88 rg 37 39 522 1 re f\nBT /FN 9 Tf 0.35 0.43 0.55 rg 38 26 Td (Desenvolvido por Stratechne  |  Emitido em ${fmt(new Date().toLocaleDateString('pt-BR'))}  |  Pagina ${pg+1}/${pageCount}) Tj ET\n`;
  let pid=id++,cid=id++;pageIds.push(pid);
  objects[pid]=`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /FN ${normalFont} 0 R /FB ${boldFont} 0 R >> >> /Contents ${cid} 0 R >>`;
  objects[cid]=`<< /Length ${bytes(content).length} >>\nstream\n${content}endstream`;
 }
 objects[catalog]=`<< /Type /Catalog /Pages ${pagesId} 0 R >>`;
 objects[pagesId]=`<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map(x=>x+' 0 R').join(' ')}] >>`;
 objects[normalFont]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
 objects[boldFont]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
 push('%PDF-1.4\n');for(let j=1;j<id;j++){offsets[j]=off;push(j+' 0 obj\n');push(objects[j]);push('\nendobj\n')}
 const xref=off;push(`xref\n0 ${id}\n0000000000 65535 f \n`);for(let j=1;j<id;j++)push(String(offsets[j]).padStart(10,'0')+' 00000 n \n');push(`trailer\n<< /Size ${id} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`);
 return new Blob(chunks,{type:'application/pdf'});
}
async function sharePdf(name,lines){const blob=createPdf(lines),file=new File([blob],name,{type:'application/pdf'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Comanda CRM Conveniência'});return}}catch(e){if(e.name==='AbortError')return}const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);toast('PDF baixado — compartilhe pelo WhatsApp ou outro aplicativo')}
function printTable(t,html){let win=window.open('','_blank');if(!win){toast('Autorize pop-ups para imprimir',true);return}const name=esc(businessInfo.name||'CRM CONVENIÊNCIA'),address=esc(businessInfo.address||''),phone=esc(businessInfo.phone||''),logo=businessInfo.logo||'/assets/logo-opcao10.png';win.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><title>${esc(t)}</title><style>@page{size:A4;margin:16mm}body{font:12px Arial,sans-serif;color:#1c2e4b;margin:0}.letterhead{display:flex;align-items:center;justify-content:space-between;background:#0a2f8f;color:white;padding:18px;border-bottom:6px solid #3776d5;border-radius:9px}.letterhead img{background:white;max-height:70px;max-width:100px;border-radius:6px;padding:4px}.letterhead h1{color:white;font-size:20px;margin:0 0 5px}.letterhead p{margin:3px 0;font-size:10px;color:#e3ecff}h2{color:#0a2f8f;margin:22px 0 6px}table{width:100%;border-collapse:collapse;font-size:11px;page-break-inside:auto}tr{page-break-inside:avoid}th{background:#e7eefb;color:#0a2f8f}td,th{padding:8px;border-bottom:1px solid #dae3ee;text-align:left}tr:nth-child(even){background:#f7f9fd}.no-print,button{display:none!important}.bar{height:9px;background:#e7edf7}.bar span{display:block;height:100%;background:#0d47c9}footer{border-top:1px solid #ccd5e3;font-size:10px;color:#718099;margin-top:25px;padding-top:10px}@media print{.letterhead{print-color-adjust:exact;-webkit-print-color-adjust:exact}th,tr:nth-child(even){print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><header class="letterhead"><div><h1>${name}</h1><p>${address}</p><p>Telefone / WhatsApp: ${phone}</p></div><img src="${logo}" alt="Logomarca"></header><h2>${esc(t)}</h2><p>Emitido em ${new Date().toLocaleString('pt-BR')}</p>${html}<footer>${name} · Desenvolvido por Stratéchne</footer><script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);win.document.close()}

function printReport(){printTable('Fechamento do mês · '+state.report.month,$('#reportPrintable').innerHTML)}
async function shareReport(){let d=state.report,text=`CRM CONVENIÊNCIA — ${d.month}\nFaturamento: ${money(d.sales.gross)}\nFiado vendido: ${money(d.sales.credit)}\nRecebimentos: ${money(d.cash.income)}\nSaídas: ${money(d.cash.expense)}\nSaldo de caixa: ${money(d.cash.net)}\nTop produtos: ${(d.items||[]).slice(0,5).map((i,n)=>`${n+1}º ${i.name} (${i.qty})`).join(', ')}`;try{if(navigator.share)await navigator.share({title:'Fechamento CRM Conveniência',text});else{await navigator.clipboard.writeText(text);toast('Resumo copiado! Para PDF, use Exportar / salvar em PDF.')}}catch(e){if(e.name!=='AbortError')toast('Não foi possível compartilhar',true)}}
function iconMarkup(id){const art={dashboard:'<rect x="3" y="3" width="7" height="9" rx="2"/><rect x="14" y="3" width="7" height="5" rx="2"/><rect x="14" y="12" width="7" height="9" rx="2"/><rect x="3" y="16" width="7" height="5" rx="2"/>',pdv:'<path d="M4 8h16l-1 13H5L4 8Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/><path d="M9 13h6m-3-3v6"/>',orders:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4h6M9 10h6M9 14h6M9 18h4"/>',products:'<path d="m12 3 9 5-9 5-9-5zM3 8v9l9 5 9-5V8M12 13v9"/>',customers:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 8a3 3 0 0 1 0 6M19 17a4 4 0 0 1 2 3"/>',suppliers:'<path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',cash:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M16 10h6v6h-6a3 3 0 0 1 0-6z"/><circle cx="16" cy="13" r=".7"/>',receivables:'<path d="M12 2v13M7 10l5 5 5-5M4 19h16v3H4z"/>',payables:'<path d="M12 22V9M7 14l5-5 5 5M4 2h16v3H4z"/>',report:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 16v-3M12 16V8M17 16v-5"/>',backup:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v7c0 2 4 4 9 4m9-11v6M3 12v7c0 2 4 3 9 3M12 13v8m-4-4 4 4 4-4"/>',business:'<path d="M3 10h18v11H3zM3 10l2-6h14l2 6M7 21v-7h6v7M16 15h3"/>',leave:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>'};return `<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${art[id]||art.dashboard}</svg>`}
function paintNav(){const menu=$('#nav');let html=`<button class="nav-button single ${state.page==='dashboard'?'active':''}" data-page="dashboard"><span class="nav-icon">${iconMarkup('dashboard')}</span><span>Painel geral</span></button>`;for(const s of menuSections){const expanded=navOpened.has(s.id);html+=`<div class="nav-section"><button class="nav-section-btn" data-toggle="${s.id}" aria-expanded="${expanded}"><span class="nav-icon">${iconMarkup(s.icon)}</span><span>${s.label}</span><span class="nav-chevron">${expanded?'⌃':'⌄'}</span></button>${expanded?`<div class="nav-section-items">${s.stock?`<button class="nav-subitem" data-page="products">Todos os produtos</button>`+s.items.map(c=>`<button class="nav-subitem" data-stock-cat="${c}">${c}</button>`).join(''):s.items.map(([id,name])=>`<button class="nav-subitem ${state.page===id?'active':''}" data-page="${id}">${name}</button>`).join('')}</div>`:''}</div>`}html+=`<button class="nav-leave" id="leaveBtn">${iconMarkup('leave')} <span>SAIR</span></button>`;menu.innerHTML=html}
function boot(){paintNav();$('#nav').onclick=async e=>{let t=e.target.closest('[data-toggle]');if(t){const k=t.dataset.toggle;if(navOpened.has(k))navOpened.delete(k);else navOpened.add(k);paintNav();return}let st=e.target.closest('[data-stock-cat]');if(st){state.stockExpanded=true;await stockFilter(st.dataset.stockCat);paintNav();return}let b=e.target.closest('button[data-page]');if(b){await page(b.dataset.page);paintNav();return}if(e.target.closest('#leaveBtn'))leaveSystem()};$('#today').textContent=new Date().toLocaleDateString('pt-BR',{dateStyle:'full'});$('#modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};$('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open');loadBusiness().finally(()=>page('dashboard'))}
boot();
